/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/la.json — nu edita de mână */
__hubApps("la",{"FreeDetect":{"line":"Vis inspicere num textus ab AI scriptus vel exscriptus videatur? Hic sunt 42 instrumenta externa et generator citationum uno loco. Applicatio ipsa nihil detegit.","detail":"Tabula 42 instrumentorum externorum ad AI et plagium detegenda et generator citationum (ISBN validat). Localiter nihil detegit; ad referentias inspiciendas adiuvat.","tags":["catalogus","citationes"]},"Arhiva-fara-frontiere":{"line":"Collectiones Internet Archive sine ratione perlustra: quaere, paginas rerum vide, praevide et amata serva. Non officialis; archive.org IP tuum et quaestiones videt.","detail":"Navigator non officialis ad collectiones Internet Archive (quaestio, paginae rerum, praevisio, amata et quaestiones recentes localiter servata), sine ratione. Wayback Machine non quaerit; archive.org IP tuum et quaestiones accipit.","tags":["archiva interretialia","fontes"]},"AcademiSearch":{"line":"Semel quaere et vide commentationes scientificas ex multis fontibus apertis. Indicem ad citationes servare potes. Interrete eget; quaestiones tuae ad illa officia eunt.","detail":"Metaquaestio academica per 11 API apertas (OpenAlex, Crossref, arXiv, etc.) cum nexibus ad portas; exportatio BibTeX/RIS/CSV. Interrete eget; quaestiones tuae ad illa officia eunt.","tags":["litteratura","fontes"]},"Surveyor":{"line":"Quos nexus situs tuus habet, et qui fracti sunt? Eos enumerat, cum ancoris et redirectionibus. Externi certo confirmari non possunt. Pro situs tuis tantum.","detail":"Nexus situs inventarium facit (HTML staticum, interfacies Anglica), ancoras et redirectiones includens. Externi ex navigatro confirmari non possunt (CORS); petitiones mittit; solos situs tuos inspice.","tags":["nexus mortui","recensio"]},"Trade-Free-Link-Guardian":{"line":"Pro situ tuo WordPress: nexus fractos invenit et reficit, sine officio externo. Contentum verum mutat, ergo prius exemplar subsidiarium fac. In vero WordPress non probatum.","detail":"Plugin WordPress quod nexus inspicit et fractos deterministice reficit, sine officio externo. Contentum verum mutat: exemplar subsidiarium fac. In vero WordPress non probatum.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Situs tuos observa et vide num adhuc respondeant. Tantum dum tabula aperta manet operatur. Pagina erroris etiam ut responsum numeratur. Interfacies Anglica est.","detail":"Monitor accessibilitatis in navigatro: inspicit num situs tui respondeant (codicem status HTTP non legit; 404/500 ut responsum numerantur). Tantum dum tabula aperta est. Interfacies Anglica.","tags":["monitoratio"]},"ScryVeil":{"line":"Securitatem domini inspice et relationem textualem ad servandum accipe. Quaedam inspectiones deesse possunt vel clavem requirere. Officia tertiorum contingit; solum dominia propria.","detail":"Diagnosis securitatis pro domino (DNS, RDAP, certificata), cum relatione textuali exportabili; inspectiones capitum et famae saepe prohibentur vel clavem requirunt. Tertios contingit; tantum pro dominiis quae possides.","tags":["OSINT","securitas"]},"Vitrina":{"line":"Pone publicam Facebook relationem in situ tuo, sine ratione, et codicem paratum ad inserendum exscribe. Non officialis; Meta IP tuum videt, et ostensio non praestatur.","detail":"Paginas/relationes publicas Facebook per plugins Meta includit, non officialis; codicem inclusionis exscribit. “Sine ratione” non significat “sine vestigiis”: Meta IP tuum videt; ostensio non praestatur.","tags":["monitoratio fontium"]},"Threads-fara-cont":{"line":"Lege publicas relationes Threads sine ratione et eas ut textum serva. Non officialis; Meta IP tuum videt, et interdum officium intermedium necessarium est.","detail":"Relationes publicas Threads per inclusionem Meta ostendit, sine ratione; servatio localis optionalis, exportatio .txt. Meta IP tuum videt; fortasse procurator CORS requiritur. Non officialis.","tags":["monitoratio fontium"]},"X-fara-cont":{"line":"Ad profilos et relationes publicas in X sine ratione accede, pluribus modis: nexu directo, archivo, quaestione vel Nitter. Contentum non legit; nexum ad archive.org mittit.","detail":"Vias sine ratione ad profilos et relationes publicas X generat: nexus directus, archivum Wayback, quaestio, Nitter. Contentum non legit; nomen usoris/nexum ad archive.org mittit.","tags":["monitoratio fontium"]},"Arhiva-LinkedIn":{"line":"Notas tuas de relationibus LinkedIn ipse insertis uno loco serva et ut textum exporta. Galeria inclusione officiali utitur, ergo LinkedIn contingit. Non officialis.","detail":"Archivum notarum de relationibus LinkedIn manu insertis (importatio CSV, exportatio Markdown) + galeria per inclusionem officialem LinkedIn (LinkedIn contingit). Non officialis.","tags":["archivatio"]},"Cadraj":{"line":"Collige manu clipsa TikTok, per auctores ordinata, et ea in lusore officiali specta. Notare potes quae iam vidisti.","detail":"Collectio manualis clipsorum TikTok per auctorem, per lusorem officialem ostensorum; nota “visum”.","tags":["monitoratio fontium"]},"FASCICUL":{"line":"Telephona in conclavi in tabulam communem in proiectore video vertit: delineationes, notae, imagines, index laseris et camera viva. In computatro probatum; in telephonis veris nondum verificatum.","detail":"Telephona ↔ proiector video: tabula communis cum delineatione, notis, imaginibus, indice laseris et camera viva, in uno fasciculo. Nexus directus WebRTC in rete locali, sine servatro tertii; relais optionalis in telephono hotspot (Android/Termux). In Chromium probatum; in telephonis veris nondum verificatum.","tags":["collaboratio"]},"INDICATIV":{"line":"Ad examen radiotelegraphiae amatoriae ANCOM para cum 723 quaestionibus, intervallis aptis repetitis, sine nexu interretiali. Non officialis; quaestionarium partim tantum verificatum est.","detail":"Exercitator sine nexu, non officialis, pro examine radiotelegraphiae amatoriae ANCOM (723 quaestiones, repetitio intervallata, quaestio in quaestionario). Non materia ANCOM; quaestionarium partim tantum verificatum est.","tags":["examen","radiotelegraphia"]},"ETER":{"line":"Radiotelegraphiam amatoriam in encyclopaedia disce cum codice Morse, exercitatore Morse, calculatoribus antennarum et quaestione per totum contentum.","detail":"Encyclopaedia radiotelegraphiae amatoriae: Morse, exercitator Koch, calculatores antennarum, quaestio globalis.","tags":["radiotelegraphia","encyclopaedia"]},"ATINGERE":{"line":"Liber in braille in ecrano tactili vertitur, cum vibrationibus, pro surdocaecis, vel in librum audibilem pro caecis. Cum lectoribus nativis non validatum; fines habet.","detail":"Libros in braille tactile vel libros audibiles convertit. Cum lectoribus nativis non validatum; fines in README vide.","tags":["accessibilitas"]},"Clopotel":{"line":"Conventum vel officinam tuam in tempore tene: horologium scaenicum cum ordine diei et signo quod finem appropinquantem monet. Romanice et Anglice.","detail":"Horologium scaenicum cum ordine oratorum (importatio textus/CSV) et signo monitorio, RO/EN.","tags":["eventa","MIT"]},"Monstrarium":{"line":"Officinam ad monstra ex materiis recyclatis facienda ordina: applicatio materias et sessiones computat et 50 monstra cum sonis, 3D et ludo educativo offert.","detail":"Ordinator pro officina monstrorum ex materiis recyclatis: materias ipse computat, horarium per series, 50 monstra originalia cum sonis, 3D et ludo educativo.","tags":["officina","MIT"]},"TranslateHub":{"line":"Inter 22 instrumenta translationis elige vel cum AI vertere cum clave tua. Textus cum AI versus ad officium Anthropic mittitur.","detail":"Index 22 instrumentorum translationis et translator AI cum clave tua. Textus AI ad api.anthropic.com mittitur.","tags":["translatio","AI"]},"DataWeave":{"line":"Tabulam aperi et eam intellege: statistica, diagrammata, tabulae pivot et correlationes. Data tua in instrumento tuo manent.","detail":"CSV/TSV/JSON in uno fasciculo explora: tabula, statistica, diagrammata, pivot et correlationes; data tua in instrumento tuo manent.","tags":["data"]},"MarkdownAtelier":{"line":"Documenta in Markdown scribe et statim vide quomodo appareant, cum formulis simplicibus, in 7 linguis, sine nexu interretiali. Textus in navigatro manent; exemplar subsidiarium serva.","detail":"Editor Markdown sine nexu cum praevisione, GFM, parte LaTeX (MathML), 7 linguis, quaestione et subsidio .json. Documenta in navigatro manent.","tags":["scriptio"]},"RegexLab":{"line":"Expressionem regularem tenta et statim vide quid congruat, cum explicationibus gradatim, probationibus et monito cum programma congelare possit.","detail":"Probatio expressionum regularium JavaScript cum explicationibus, probationibus et monito ReDoS.","tags":["progressio"]},"SEOptimum":{"line":"Inspice quam bene pagina interretialis pro machinis quaesitoriis parata sit. 20 instrumenta habet, analysin paginae et praevisionem apparentiae in eventibus quaestionis includentia.","detail":"20 instrumenta SEO in navigatro: analysis paginae, praevisiones SERP.","tags":["interrete"]},"SEVA":{"line":"Plura disce de somno, rhythmo corporis cotidiano, respiratione et nutritione, in encyclopaedia quam etiam audire potes. Ad informandum tantum; non consilium medicum.","detail":"Encyclopaedia salubritatis: somnus, rhythmus circadianus, respiratio, nutritio; auditio recitata. Informativa; non consilium medicum.","tags":["salus"]},"PULS":{"line":"Quid facis donec ambulance adveniat? Manuale primae opis Romanice, cum metronomo CPR et charta urgentiae optionali. Clinice non validatum; numerum 112 voca.","detail":"Manuale primae opis Romanice (CPR cum metronomo, tourniquet), cum quaestione et charta urgentiae optionali. Contentus a specialista clinice non validatus; cursum auctoratum non substituit. In casu urgenti numerum 112 voca.","tags":["salus","casus urgens"]},"VATRA":{"line":"Quid facis si aqua, ignis vel tectum in silvestribus deest? Encyclopaedia superviventiae, sine nexu interretiali, cum quaestione et notis. Ad educandum tantum; in casu urgenti 112 voca.","detail":"Encyclopaedia superviventiae sine nexu (aqua, ignis, tectum, navigatio), cum quaestione et notis localiter servatis. Materia educativa, cursum primae opis non substituit; in casu urgenti 112 voca.","tags":["opus in agro"]},"Eclipsa-2027":{"line":"In tabula geographica vide ubi et quam diu eclipsis solis totalis diei 2 Augusti 2027 duret, cum urbibus et quaestione locorum, sine nexu interretiali. Valores approximati; Solem sine filtris ne specta.","detail":"Tabula geographica sine nexu eclipsis totalis diei 2 Augusti 2027, cum durationibus, tectura per urbem et quaestione locorum. Valores indicativi; Solem sine filtris certificatis ne specta.","tags":["astronomia"]},"orarium":{"line":"Quota hora nunc est in Marte, in Luna vel in asteroide? Vide tempus locale vivum in 45 corporibus caelestibus. Exemplar approximatum, sine nexu interretiali; non ad navigationem.","detail":"Tempus in omni mundo: tempus locale vivum in 45 corporibus (Luna, Mars, planetae, lunae, asteroides), celeritas horologii ad Terram relata, distantia et tempus itineris duplicis, convertor zonarum horariarum et mappae colonizationis. Exemplar indicativum, sine nexu; non ad navigationem. Mediam noctem et meridiem in quoque corpore, fenestras transmissionis Terra–corpus et nexum ad TerRa includit.","tags":["astronomia","tempus"]},"TerRa":{"line":"Globus 3D et mappa diem et noctem in Terra, Luna et planetis ostendentes. Positiones satellitum circiter 3 menses vetustae esse possunt donec interrete renoves.","detail":"Globus 3D et mappa: terminator, Luna, planetae. Satellites instantaneo vetusto (~3 menses) sine nexu utuntur; pro positionibus currentibus interrete renova. Nexus unicus pro omni aspectu; caelum ex quovis ex 45 corporibus ORARIUM, utroque modo coniunctum.","tags":["astronomia"]},"Horizons.BeyondLimits":{"line":"Per historiam universi a Magno Crepitu ad finem iter fac, in 91 terminis. Futurum est speculatio scientifica, non praedictio certa.","detail":"Mappa temporalis a Magno Crepitu ad finem universi: 91 eventa, exportatio Markdown; futurum speculativum est, non praedictio validata.","tags":["cosmologia"]},"Hyper4D":{"line":"Vide quales figurae quattuor dimensionum sint: eas in ecrano roga et ex pluribus angulis specta. Imagines servari possunt.","detail":"Geometria 4D in SVG: sectiones 3D corporum 4D et polytoporum cum proiectionibus 4D→3D→2D tempore reali rotatis, exportatio SVG.","tags":["mathematica"]},"ExploratoriiEco":{"line":"Manuale agri pro naturae amatoribus: a classificatione viventium et vestigiorum eorum ad biomata Romaniae, ephemeridem, ethicam et casus urgentes.","detail":"Manuale agri pro naturalistis in 20 sectionibus: classificatio vitae, signa et vestigia, biomata Romaniae, calculatores, ephemeris, ethica, casus urgentes et glossarium.","tags":["natura"]},"FieldObserver":{"line":"Observationes tuas in agro nota, et telephonum sponte lectiones ex sensoribus suis addit. Archivum excursionum tuarum servas.","detail":"Ephemeris observationum in agro per sensores telephoni; archivum, exportatio JSON/CSV.","tags":["opus in agro"]},"VietAR":{"line":"Plantam vel animal photographa vel recipe et ideam speciei accipe, ex 519 Romaniae. Errare potest; nihil ex eo comede.","detail":"Identificatio indicativa 519 specierum Romaniae ex imagine/sono; errare potest, plantas vel fungos ex ea ne comede. Exemplaria a tertiis deferuntur; non plene sine nexu.","tags":["biodiversitas"]},"VOIAJOR":{"line":"Trajectorias Voyager 1 et 2 ab anno 1977 ad miliardum annorum in futurum sequere, in quavis scala, a planetis ad Viam Lacteam. Exemplar indicativum, non navigatio.","detail":"Simulatio trajectoriarum Voyager 1 et 2 (a 1977 ultra miliardum annorum): arcus ballistici inter praetervolationes veras, extrapolatio cum gravitate solari et dynamica galactica locali, heliosphaera, nubes Oort et 19 stellae propinquae cum motu proprio.","tags":["Voyager","simulatio"]},"Nemurirea":{"line":"Disce quomodo corpus senescat et quid scientia de horologiis biologicis et longaevitate dicat, deinde te ipsum quiz proba. Non consilium medicum.","detail":"Essaium interactivum de horologiis biologicis et scientia longaevitatis, cum quiz finali. Ad informandum, non consilium medicum.","tags":["biologia"]},"IncredibleCosmos":{"line":"Planetas et stellas ita pone ut gravitas eorum cometam ad metam ducat. 108 gradus, tres difficultates et usque ad tres stellas per gradum.","detail":"Aenigma gravitatis: planetas et stellas pone ut gravitas eorum cometam ad metam ducat; 108 gradus in 12 categoriis, tres difficultates, aestimatio 1–3 stellarum, cum quaestione.","tags":["ludus","physica"]},"Cupa-Mondiala-2026":{"line":"Lude in Cupa Mundiali 2026 et specta torneamentum imaginarium evolvi. Eventus fortuiti sunt, non praedictiones; non officialis.","detail":"Simulator fictus, non officialis, Cupae Mundialis 2026: eventus fortuiti, non praedictiones; cum FIFA non coniunctus.","tags":["simulatio","non officiale"]},"AGORA":{"line":"Quomodo euro natum est et quid Romaniae significat? 59 sectiones, a Maastricht ad ECB, et consilia viatoribus. Non officialis.","detail":"Atlas informativus areae euro in 59 sectionibus: a Maastricht et ECB ad Romaniam et euro, cum manuali viatoris. Non officialis, sine valore iuridico.","tags":["oeconomia","UE"]},"URME":{"line":"Para te ad iter pedestre in semita Colți–Aluniș in Buzău: plantae, electrum, fossilia, tempora ortus et occasus solis, instrumenta. Mappa ad navigationem non est.","detail":"Manuale itineris pedestris informativum, non officiale, pro Colți–Aluniș (plantae, electrum, fossilia), cum ortu/occasu solis et indice instrumentorum. Mappa schematica, non ad navigationem; extractio ex area protecta prohibita est.","tags":["natura","Buzău"]},"Belot-fara-frontiere":{"line":"Belote et cognata eius ex aliis terris disce, deinde ad mensam lude: tu et socius AI contra duos adversarios AI. Tabulam punctorum includit.","detail":"Atlas familiae belote/bela/klaverjas/jass et ludus quattuor lusorum (tu et socius AI contra duos adversarios AI); Belot Romanum primarium est; tabula punctorum.","tags":["chartae lusoriae","AI"]},"Scopone-fara-frontiere":{"line":"Disce quomodo Scopone natus sit, quae regulae eius sint et quomodo a regione ad regionem differant, deinde contra computatrum lude, quod indicia dare potest.","detail":"Atlas Scopone (15 tabulae: origo, regulae, differentiae regionales) et ludus contra AI localem (heuristica / Monte-Carlo), cum indiciis; semina Italica vel Gallica.","tags":["chartae lusoriae","AI"]},"Solitaire-fara-frontiere":{"line":"Ludos solitarios ut Klondike, FreeCell vel Spider perlustra et eos lude. Cum haeres, indicium pete vel computatrum solvere sine.","detail":"Atlas ludorum solitariorum (Klondike, FreeCell, Spider et alii) in motore communi; “Indicium” a solutore cum limite nodorum/temporis et solutione automatica optionali.","tags":["chartae lusoriae"]},"Sudoku-fara-frontiere":{"line":"136 genera Sudoku, a classico ad killer vel 3D, ad perlustrandum et ludendum. Explicationibus gradatim adiuvat et aenigmata tua solvit.","detail":"Atlas 136 variantium Sudoku (classicum, killer, jigsaw, Graeco-Latinum, 3D et multae aliae), cum generatore solutionis unicae, solutione gradatim explicata, 7 modis ludi et solutore.","tags":["aenigma"]},"Domino-fara-frontiere":{"line":"Historiam et regulas domino disce, deinde ad mensam lude contra unum ad tres adversarios a computatro ductos. Motum revocare potes.","detail":"Atlas domino (origo, regulae, approximationes) et mensa ludi contra 1–3 lusores AI, cum tribus gradibus; revocatio motus.","tags":["domino","AI"]},"Mahjong-fara-frontiere":{"line":"8 varietates mahjong explora et solitarium vel ludum quattuor lusorum lude, cum tribus adversariis simplicibus a computatro ductis. Sine nexu operatur.","detail":"Atlas 8 variantium mahjong, solitarium et mahjong quattuor lusorum (riichi, Hong Kong, Sichuan) contra 3 AI heuristicas simplices. Sine nexu.","tags":["Mahjong","AI"]},"Go-fara-frontiere":{"line":"Disce unde Go veniat et quomodo ludatur, deinde te contra computatrum tempta, quod indicia dare potest. Nulla data per interrete mittit.","detail":"Atlas Go (18 tabulae: origo, regulae, approximationes) et ludus contra AI localem (Monte-Carlo, non LLM), cum SGF et indiciis; nullae petitiones ad rete interretiale.","tags":["Go","AI"]},"Zaruri-fara-frontiere":{"line":"26 ludi tesserarum ad legendum, 12 ex eis contra computatrum ludibiles, et simulator iactuum cum probabilitatibus. Nulla pecunia involvitur; sine nexu.","detail":"Atlas 26 ludorum tesserarum; 12 ludibiles contra AI didacticam (non LLM), et simulator NdM cum probabilitatibus exactis. Non ludus aleae; sine nexu.","tags":["tesserae"]},"Sah-fara-frontiere":{"line":"Plus quam 700 variantes scacchorum ad explorandum, cum parvo dictionario terminorum; pro multis contra computatrum ludere potes. Sine nexu operatur.","detail":"706 ingressus variantium scacchorum (aliqui tantum cum fonte verificato; aliqui synthetici) et 299 termini lexici. Sine nexu, cum motore locali pro multis variantibus.","tags":["scacchi"]},"Dame-fara-frontiere":{"line":"25 variantes latrunculorum contra computatrum lude et ludum tuum serva. Regulae 16 ex eis approximatae sunt tantum, signo ⚠ notatae.","detail":"25 variantes latrunculorum contra AI didacticam ludibiles, cum exportatione ludi; 16 regulas approximatas habent (signo ⚠ notatae).","tags":["latrunculi"]},"Table-fara-frontiere":{"line":"Backgammon, Tavli, Narde et variantes Romanicae tabulae, ad legendum et ludendum: 17 variantes contra computatrum, cum tabula clavium vel mure.","detail":"Atlas ludibilis familiae backgammon: backgammon, Tavli, Tavla, Narde, Gul Bara et variantes Romanicae; 17 variantes contra AI didacticam; ludus per tabulam clavium.","tags":["tabula"]},"Remi-fara-frontiere":{"line":"Familiam rummy explora et 19 variantes contra computatrum lude, cum statisticis. 8 linguas habet et tesseras vel chartas magnas, facile visibiles.","detail":"Atlas familiae ludorum rummy: 19 variantes ludibiles contra AI localem, cum statisticis; interfacies in 8 linguis, cum tesseris et chartis magnis.","tags":["rummy"]},"Carti-de-joc-fara-frontiere":{"line":"A Solitario et Old Maid ad poker: 17 ludi chartarum cum regulis explicatis, quorum 8 statim ludere etiam potes.","detail":"Atlas interactivus ludorum chartarum, a Solitario et Old Maid ad poker: 17 ludi cum tabulis regularum, 8 ex eis ludibiles.","tags":["chartae lusoriae"]},"Undava":{"line":"Quiz cum amicis fac vel lude, in eodem telephono vel computatro, et quaestiones male responsas iterum lude. Simile Kahoot, sed non coniunctum.","detail":"Quiz in modo Kahoot (non coniunctum), in uno fasciculo: solitarie vel vicissim in eodem instrumento, cum repetitione errorum. Ludus vivus tantum in editione servatri est.","tags":["quiz","educatio"]},"AI-Liber":{"line":"Cum pluribus adiutoribus AI uno loco collocutor, etiam cum quibusdam qui in computatro tuo operantur. Nuntii ad provisorem quem eligis eunt; AI errare potest.","detail":"Colloquium cum pluribus provisoribus AI, etiam localibus (Ollama, WebLLM). Nuntii ad provisorem quem eligis eunt; responsa AI falsa esse possunt.","tags":["AI"]},"LocalMind":{"line":"Cum parvo adiutore AI collocutor qui in ipso navigatro tuo operatur. Exemplaria semel ex interrete deferuntur; errare potest.","detail":"Colloquium cum exemplaribus parvis (Qwen3, LFM2) localiter in navigatro operantibus (WebGPU). Exemplaria ex Hugging Face veniunt; errare potest. Servatrum localem vel paginam publicam requirit.","tags":["AI localis"]},"PromptVault":{"line":"Plus quam 500 mandata parata pro adiutoribus AI, ex quibus eligis et amata notas. Textus tuos proprios non servat.","detail":"Bibliotheca 500+ mandatorum cum amatis, non administrator mandatorum tuorum propriorum.","tags":["mandata AI"]},"ARENA":{"line":"Duo exemplaria AI caeco responsa dare fac et optimum suffragio elige; ordo in computatro tuo servatur. Claves proprias requirit.","detail":"Certamina caeca inter exemplaria AI cum ordine Elo locali (exportatio CSV). Claves API proprias vel servatra localia requirit; exemplaria demonstrativa simulata sunt.","tags":["aestimatio AI"]},"Nexus-fara-frontiere":{"line":"Cum adiutoribus AI plurium provisorum collocutor, cum quaestione colloquiorum et servatione. Interrete et claves proprias requirit, quae non cryptatae servantur.","detail":"Cliens colloquii AI cum clavibus API tuis (Anthropic, OpenAI, Google, compatibiles cum OpenAI), cum quaestione et exportatione Markdown; “agentes” mandata sunt. Interrete requirit; claves non cryptatae servantur.","tags":["agentes"]},"VoiceAtelier":{"line":"Audi quomodo centum voces artificiales in multis linguis sonent et disce quomodo liber audibilis fiat. Specimen interretiale textum ad officia externa mittit, solum cum consensu tuo.","detail":"Catalogus 427 vocum neuralium (141 locales) et manuale librorum audibilium. Specimen interretiale textum ad relais et ad Microsoft mittit, solum cum consensu tuo. Non studium TTS.","tags":["vox"]},"Trusa-fara-frontiere":{"line":"Instrumentarium 15 instrumentorum parvorum cotidianorum: notae, tabula calculatoria, Markdown, tesserae secretae, ephemeris pecuniae et plura. Cum YunoHost, cuius categoriae eum inspiraverunt, nexum officialem non habet.","detail":"Series 15 modulorum parvorum a fundamentis scriptorum (notae, tabula calculatoria, Markdown, tesserae secretae, ephemeris pecuniae et plura), categoriis applicationum YunoHost inspirata; non coniuncta.","tags":["utilitates"]},"API-fara-frontiere":{"line":"Tempestatem, imagines NASA, positionem ISS et multa alia data viva uno loco vide. Interrete eget et cum officiis veris non probatum est.","detail":"52 widgets: 47 per API publicas (interrete egent; aperiendo interrete sponte Open-Meteo, NASA et ISS contingit) et 5 utilitates locales. Contra servatra vera non probatum.","tags":["API"]},"OmniHost":{"line":"Magna sarcina plus centum instrumentorum laboris uno loco collectorum. Quattuor officia externa contingit; singula in README sunt.","detail":"Series productivitatis (~4 MB, 141 moduli). Quattuor hospites externos contingit; README vide.","tags":["series"]},"VNTV":{"line":"Praevisiones VideoNeat sicut canalem televisificum numquam cessantem ludere sine. Interrete eget; in modo P2P, adresa tua ceteris spectatoribus visibilis est.","detail":"Praevisiones VideoNeat ut programma televisificum continuum, et addon Stremio. Interrete requirit (videoneat.com, videos.trom.tf); in modo P2P, IP tuum ceteris spectatoribus visibile est.","tags":["media","MIT"]},"OSATURA":{"line":"Delineationes 2D ad vitam excita: eas in “sceleto” affige, in motum pone et animationem in pluribus formis exporta. Versio alpha, adhuc paulum probata.","detail":"Motor rigging et animationis vectoriae 2D in Rust (ossa, IK, skinning, physica, machinae statuum) cum studio in navigatro et exportatione in SVG, PNG, GIF, Lottie et glTF. Programma nativum (linea mandatorum + studium) et modulus WebAssembly, non fasciculus HTML unicus; alpha, ab usoribus adhuc paulum probata. Licentiae: bibliothecae MPL-2.0, CLI AGPL-3.0-or-later.","tags":["animatio","MPL/AGPL"]},"OAZA":{"line":"340 officia interretialia gratuita perlustra, plerumque sine ratione, in uno catalogo collecta. Index mense Iunio 2026 inspectus est, sed non sponte.","detail":"Catalogus 340 officiorum interretialium tertiorum gratuitorum, plerumque sine ratione usurpabilium (non sponte verificatus; mense Iunio 2026 inspectus).","tags":["officia"]},"VaultCrypt":{"line":"Habesne aliquid ab oculis curiosis custodiendum? Fasciculos et textus tessera secreta claude, in ipso navigatro. Tessera amissa recuperari non potest.","detail":"Cryptatio AES-256-GCM fasciculorum et textuum in navigatro. A nemine independenti recensita; tessera amissa recuperari non potest.","tags":["securitas"]},"Akasha":{"line":"Libellus cum etiquettis, quaestione et nexibus inter paginas, qui sine nexu operatur. Ne quid amittas, exemplar recens fasciculi deferes.","detail":"Notae sine nexu in uno fasciculo, cum etiquettis, quaestione et nexibus [[Titulus]]; ut data tua serves, exemplar recens fasciculi defer (quine).","tags":["notae"]},"CLEPSIDRA":{"line":"Horologium retrogradum, alarma et horaria pro diebus laboris et fine hebdomadis. Dies festos et eventa tua observat.","detail":"Horologium inversum, alarma, horaria dierum laboris/finis hebdomadis, dies festi, eventa.","tags":["tempus"]},"Origami":{"line":"Chartam plicare gradatim disce: signa, technicae et exemplaria illustrata. Applicatio meminit ubi desieris.","detail":"Manuale origami: notatio, technicae, exemplaria gradatim, cum progressu localiter servato.","tags":["ars"]},"Zicala":{"line":"Proverbium Romanicum cotidie, ex collectione 550. Quaerere et amata servare potes; commentaria cum auxilio AI scripta sunt.","detail":"550 proverbia Romanica cum proverbio diei, quaestione et exportatione/importatione amatorum; commentaria SWOT/TOWS ab AI adiuvantur.","tags":["cultura"]},"Limpezimea":{"line":"Lege novellam scientificam “Limpezimea” in septem linguis. Chronica et studium criticum comitantia cum auxilio AI (Claude) scripta sunt.","detail":"Fabula scientifica “Limpezimea” in 7 linguis, editio lectionis. Apparatus criticus (chronica, studium) cum auxilio AI (Claude) scriptus est.","tags":["litteratura"]},"Nota-Zero":{"line":"Fabula speculativa de theoria chordarum, Romanice, Anglice et Gallice, cum notis ideas scientificas explicantibus. Fabula est, non fons academicus.","detail":"Fabula speculativa de theoria chordarum, Romanice, Anglice et Gallice, cum notis scientificis explicativis (fabula, non fons academicus).","tags":["litteratura"]},"Pendulul":{"line":"Planeta inter tres stellas et foramen nigrum oscillat: novella scientifica in novem voluminibus, ab Alexio cum Claude scripta. Cum simulatione 3D, lectore servabili ad legendum sine nexu, EPUB et PDF.","detail":"Novella scientifica novem voluminum ab Alexio cum Claude scripta: planeta inter tres stellas et foramen nigrum oscillat. Simulationem 3D et lectorem libri in uno fasciculo HTML, quem servare et sine nexu legere potes, itemque EPUB et PDF includit.","tags":["litteratura"]},"PrintreInteligente":{"line":"Novellam scientificam interactivam ingredere, cum personis ab equipa Artemis 2 inspiratis. Recensiones fictae sunt; translatio, vox et functiones AI officia externa utuntur.","detail":"Novella scientifica interactiva, fabula cum personis ab equipa Artemis 2 inspiratis; recensiones fictae sunt. Translatio, vox interretialis et functiones AI officia externa utuntur.","tags":["litteratura"]},"BorderlessMelodies":{"line":"Musicam quae se ipsa componit audi, in ipso navigatro. Eam ut sonum exportare potes, et horologium somni adest.","detail":"Musica procedualis in Web Audio, cum exportatione soni et horologio somni.","tags":["musica"]},"EcoulSpectral":{"line":"Sonum ut imaginem vide, partem quae te vexat elige et eam isola vel dele. Reductionem strepitus, detectionem vocis et servationem in WAV includit.","detail":"Editor spectrogrammatis localis: regionem temporis–frequentiae nota et eam isola vel remove; detectio vocis, reductio strepitus, exportatio WAV.","tags":["sonus"]},"Constelar":{"line":"Cum sociis virtualibus qui colloquia tua meminerunt collocutor. Ex defectu regulis simplicibus respondent; vera AI tantum si provisorem eligis, et nuntii tui ad eum eunt. Adultis tantum.","detail":"Socii colloquentes cum memoria locali. Ex defectu motor simplex regulis nixus; vera AI tantum si provisorem eligis (nuntii ad eum mittuntur). Pro adultis; therapiam non substituit.","tags":["AI"]},"Tarot":{"line":"Historiam tarot, symbola chartarum et modum legendi disce, ut phaenomenon culturale visum. Cursus interactivus ad ritmum tuum sequendus.","detail":"Cursus interactivus: historia, symbola et lectio chartarum, ut phaenomenon culturale.","tags":["cultura"]},"Numerologie":{"line":"Numerologiam ut traditionem symbolicam explora, in quattuor gradibus cum exercitiis, glossario, ephemeride et calculatore. Sine validatione scientifica praesentatur.","detail":"Cursus interactivus de numerologia ut traditione symbolica: quattuor gradus, exercitia, glossarium, ephemeris et calculator; sine validatione scientifica praesentatur.","tags":["cultura"]},"PUNCTUM":{"line":"Atlas educativus acupressurae et therapiarum punctualium: plus quam 400 puncta in mappis interactivis, routinae sui curae cum sessionibus ductis, testimonia et securitas. Medicum non substituit.","detail":"Atlas educativus therapiarum punctualium (acupunctura, acupressura, moxibustio, cuppatio, therapia auricularis, reflexologia et plura): 410 puncta in 14 meridianis, 60 variantes cum gradu testimoniorum, mappae SVG, condiciones et routinae, cursus, quiz, chartae memoriae et inspectiones securitatis personales.","tags":["salus","testimonia"]},"Reiki":{"line":"Disce quid sit Reiki, praxis spiritualis, et quid investigatio dicat: testimonia insufficientia ullius effectus praeter relaxationem inventa sunt. Medicum non substituit.","detail":"Cursus de Reiki, praxi spirituali: recensiones testimonia insufficientia ullius effectus praeter relaxationem/placebo inveniunt; medicum non substituit.","tags":["cultura"]},"Bioenergoterapie":{"line":"Cursus qui explicat quid sit therapia bioenergetica et unde veniat. Praxis testimoniis scientificis sanationis caret et medicum non substituit.","detail":"Cursus de therapia bioenergetica, praxi sine testimoniis scientificis sanationis; medicum non substituit.","tags":["cultura"]},"CHIROMANTIA":{"line":"Atlas chiromantiae interactivus: mappa palmae cum lineis, montibus, digitis et generibus manuum, ut traditio culturalis lecta, cum sectione de scientia et cogitatione critica. Sine validatione scientifica.","detail":"Atlas chiromantiae interactivus: mappa palmae SVG (sinistra/dextra), lineae, montes, digiti, genera manuum, dermatoglyphi, mensurae 2D:4D, lectio ducta, chartae memoriae, quiz, probatio caeca Barnum et simulator cold-reading; omnis adfirmatio gradum testimoniorum habet.","tags":["chiromantia","cultura"]},"Radiestezie":{"line":"18 gradus de radiaesthesia percurre, cum glossario, ephemeride praxis et appendicibus internationalibus. Ab initio declarat se validatione scientifica carere.","detail":"Cursus in 18 gradibus de radiaesthesia, cum glossario, ephemeride praxis et appendicibus internationalibus; ab initio declarat se validatione scientifica carere.","tags":["cultura"]},"Inforenergetica":{"line":"Disce quid inforenergetica, praxis non conventionalis, adfirmet, in cursu structurato. Validatione scientifica caret et non est consilium medicum.","detail":"Cursus de inforenergetica, praxi non conventionali sine validatione scientifica; non consilium medicum.","tags":["cultura"]},"ECLIPSA":{"line":"Invenies in qua domo astrologica eclipsis in charta natali tua cadat, et proximas 12 eclipses. Calculatio approximata est et interpretatio symbolica, sine validatione scientifica.","detail":"In qua domo astrologica eclipsis in charta natali cadat, et proximae 12 eclipses. Calculatio astronomica localis, approximata; interpretatio symbolica, astrologia validatione scientifica caret.","tags":["astrologia"]},"Afrodisiace-fara-frontiere":{"line":"Lege de 22 cibis et plantis traditione cum cupiditate coniunctis, quoque cum gradu testimoniorum. Manuale culturale pro adultis, non consilium medicum.","detail":"Manuale culturale de 22 cibis et plantis traditione cum cupiditate coniunctis, cum gradu testimoniorum per ingressum. Educativum, non consilium medicum.","tags":["cultura"]},"CalmWaves":{"line":"Musica ambientalis in loco generata, ad relaxationem et somnum. Non instrumentum medicum; sectio investigationis non independenter verificata est. Consilium medici pete (epilepsia).","detail":"Musica ambientalis generativa ad relaxationem/somnum. Non instrumentum medicum; sectio investigationis non independenter verificata est. Consilium medicum pete (epilepsia).","tags":["sonus"]},"ASMR":{"line":"Paysage sonorum relaxans tuum ex stratis ambientalibus, sonis tactus et pulsibus binauralibus construe. Horologium somni habet, et mixturam tuam cum aliis communicare potes.","detail":"Mixtor sonorum relaxationis tempore reali generatus (Web Audio): strata ambientalia, soni tactus, pulsus binaurales et horologium somni; mixtura communicabilis.","tags":["sonus"]},"NOMIA":{"line":"Qualis esse possit primus contactus inter homines, intellegentias artificiales et alia genera mentium? 1001 scaenaria imaginata, fabula, non facta. Etiam sine nexu operatur.","detail":"Simulator conceptualis protocollorum contactus Homo–AI–NHI, 1001 ingressus, comes anthologiae “Printre inteligențe”. Fabula/speculatio, non facta verificata; PWA sine nexu, RO/EN.","tags":["fabula","speculatio","PWA"]},"ValeaPlopului1972":{"line":"Casum UFO anni 1972 ab exteriore, ab interiore et in simulatione vide, in 3D reconstructum. Hypothesis imaginata est, non testimonium.","detail":"Reconstructio 3D casus UAP Valea Plopului (1972): exterior, simulatio, interior imaginatum. Speculativa, in fontibus publicis non verificatis fundata, sine consensu personarum nominatarum; non testimonium.","tags":["UAP","3D","fabula"]},"HoroScop":{"line":"Positiones planetarum pro data et loco computa, deinde chartam natalem, aspectus et compatibilitatem explora. Astrologia symbolica, sine fundamento scientifico. Sine nexu.","detail":"Ephemeris personalis sine nexu: positiones planetarum in navigatro computatae (praecisio reducta), charta natalis, aspectus, synastria. Astrologia symbolica, sine validatione scientifica; licentia MIT.","tags":["astrologia","ephemeris","sine nexu"]},"Aurora":{"line":"Sonos lenientes, sonos leniter pulsantes audi et ducem respirationis sequere. Ad relaxationem tantum, non curatio. Sine nexu operatur.","detail":"Sanctuarium sonorum: soni chakrarum, pulsus binaurales et dux respirationis, sine nexu. Ad relaxationem tantum, non medicina; frequentiae validatione scientifica carent. Licentia MIT; inceptum independens.","tags":["meditatio","sonus","relaxatio"]},"NumeroLogIA":{"line":"Disce quid numerologia, astrologia Sinica BaZi et biorhythmus de die natali tuo dicant, cum omni calculatione gradatim explicata. Systema symbolicum, sine fundamento scientifico.","detail":"Numerologia Pythagorica/Chaldaica, BaZi et biorhythmus in 7 linguis, calculationes gradatim, imagines in JSON exportabiles; oraculum AI optionale per exemplar tuum. Systema symbolicum, sine validatione scientifica; licentia MIT.","tags":["numerologia","AI","sine nexu"]},"FrequencyLaboratory":{"line":"Sonos, effectus et probationes auditus in parvo laboratorio audio tempta. Effectus “therapeutici” non probati sunt et medicum non substituunt. Sine nexu.","detail":"Laboratorium audio in navigatro (oscillatores, binaurales, effectus, analysatores, probationes auditus), sine nexu. Ad informandum tantum: praesettings “therapeutica” effectum medicum probatum non habent; non instrumentum medicum.","tags":["sonus","laboratorium","sine nexu"]},"generator-frecvente":{"line":"Sonos puros et sonos duplices pulsantes crea, praesettings notas audi et inspectionem approximatam quam bene audias accipe. Non instrumentum medicum. Sine nexu.","detail":"Generator sonorum in navigatro (binaurales, sequencer, EQ, probatio auditus indicativa, quaestio praesettingum), sine nexu. Ad informandum tantum: praesettings Solfeggio/Schumann validatione scientifica carent; non instrumentum medicum.","tags":["sonus","generator","sine nexu"]},"ACORDAJ":{"line":"Plus mille cursus et initiationes spirituales perlustra, cum contextu historico et visu critico. Cum situ fontis non coniunctum et sine validatione scientifica. Sine nexu.","detail":"Atlas sine nexu 1134 cursuum/initiationum spiritualium (index ex cursurispirituale.webnode.ro, non coniunctus), cum contextu historico et iudicio critico; sine validatione scientifica.","tags":["spiritualitas","atlas","iudicium criticum"]},"Profund":{"line":"150 quaestiones quae colloquium ultra sermonem levem ducunt, inter amicos vel in familia. In ecrano lude vel imprime, cum horologio optionali.","detail":"Ludus 150 quaestionum ad colloquia significantia (RO/EN/FR), interretialis vel impressus, cum lusoribus et horologio optionali; ex deepcards.org adaptatus, originalia dominorum iurium manent (MIT tantum pro codice et parte originali).","tags":["conversatio","chartae lusoriae","sine mercatura"]},"Universul-Observabil":{"line":"Quantus est Universus quem videre possumus? Tres mappas (linearem, planam, in spatio) compara et calculationes cosmologicas fac. Numeri non independenter verificati sunt.","detail":"Pagina centralis visualizationes 1D, 2D et 3D Universi observabilis praesentans et comparans, cum calculatore cosmologico sine nexu; numeri et recordationes ex catalogo Maii 2026 sunt, non independenter verificati. RO/EN.","tags":["astronomia","cosmologia","visualizatio"]},"Universul-Observabil-1D":{"line":"A nobis incipe et ad oram Universi visibilis proficiscere, 112 galaxias in uno axe positas praetereundo. Tonus ironicus, valores rotundati, propositum educativum.","detail":"Mappa 1D Universi observabilis: 112 galaxiae in axe radiali (tempus, distantia, redshift), cum tabula datorum et exportatione CSV. Educativa, cum tono ironico; valores rotundati, recordationes ad diem catalogi (Maius 2026).","tags":["astronomia","cosmologia","visualizatio"]},"Universul-Observabil-2D":{"line":"Mappa galaxiarum in editione satirica “Terra plana”: iocus, Terra plana non est. Inter 111 galaxias zoom fac; distantiae approximatae sunt. Sine nexu.","detail":"Mappa 2D interactiva universi observabilis (111 galaxiae, scala logarithmica, data JWST) in editione satirica “Terra plana”: parodia, Terra plana non est; distantiae approximatae sunt. RO/EN, sine nexu.","tags":["astronomia","satira","cosmologia"]},"Universul-Observabil-3D":{"line":"Inter plus quam 115 galaxias in mappa 3D vola, cum itineribus ductis et provocationibus. Valores approximati sunt.","detail":"Mappa 3D interactiva (WebGL) universi observabilis: 115+ galaxiae, 12 horizontes, 30 itinera, provocationes in manuali, exportatio GLB/CSV/BibTeX. Valores approximati; recordationes JWST ad Maium 2026.","tags":["astronomia","cosmologia","3D"]},"QSO":{"line":"Contactus radiophonicos stationis tuae radiotelegraphiae amatoriae observa, cum tempore UTC, locatoribus et statisticis. Non officialis; calculationes approximatae sunt.","detail":"Ephemeris stationis radiotelegraphiae amatoriae non officialis: QSO cum horologio UTC, importatio/exportatio ADIF 3.1, locatores Maidenhead, inspectiones duplicatorum, statistica. Tabula praefixorum partialis (non DXCC); calculationes approximatae.","tags":["radiotelegraphia","ephemeris"]},"Curatitor":{"line":"Vide quid photographiae et fasciculi tui revelent (locum, cameram, auctorem) et haec data remove antequam eos mittas. Facies vel alium contentum visibilem non celat.","detail":"Metadata fasciculorum localiter ostendit et removet (GPS, camera, auctor, programma) sine pixelis vel sono recodificandis, et eventum iterum inspicit. Contentum non anonymizat (facies, strepitus sensoris).","tags":["metadata","secretum"]},"Poteca":{"line":"Vestigia in itinere pedestri vel birota notata aperi et vide distantiam, ascensum et profilum altitudinis. Ea etiam secare vel coniungere potes. Sine mappa; ascensus aestimatur.","detail":"Visor et editor vestigiorum GPX/GeoJSON/KML/CSV: statistica, profilum altitudinis, sectio, coniunctio, simplificatio, exportatio. Sine mappa fundamentali; ascensus/descensus aestimationes sunt.","tags":["GPX","vestigia"]},"Orar":{"line":"Calendarium et ordinator hebdomadalis quem per diem, hebdomadam vel mensem videre potes, cum diebus festis publicis Romaniae. Alarmae tantum dum pagina aperta manet sonant.","detail":"Calendarium et ordinator hebdomadalis: aspectus mensis/hebdomadae/diei/ordinis diei, recurrentiae RFC 5545, zonae horariae, dies festi publici Romaniae, importatio/exportatio .ics. Alarmae tantum dum tabula aperta est sonant.","tags":["calendarium","tempus"]},"Alfabete":{"line":"Morse, braille, alphabetum phoneticum, semaphorum vexillorum et cryptographias veteres disce et exerce, deinde tabulam imprime. Cryptographiae veteres secreta non protegunt.","detail":"Referentia, convertor, exercitator et tabula imprimibilis pro Morse, braille (gradus 1), alphabetis phoneticis, semaphoro, Baudot, basibus numerorum et cryptographiis classicis. Cryptographiae classicae nullam securitatem praebent.","tags":["codices","discere"]},"Fabrica":{"line":"Cursum ut textum simplicem scribe et in paginam cum lectionibus, probatione finali et testimonio imprimibili converte. Testimonium valorem officialem non habet.","detail":"Fabrica cursuum et quiz: cursum in Markdown simplici scribe et ut unum fasciculum HTML sibi sufficientem exporta, cum progressu locali, probatione finali et testimonio imprimibili (sine valore accreditationis).","tags":["cursus","compositio"]},"Bolta":{"line":"Qualis erat caelum supra te, in quovis loco et quovis die inter 1900 et 2100? Solem, Lunam, planetas et stellas vide, itemque eclipsim 2027. Valores computati sunt, non officiales. Sine nexu.","detail":"Planetarium sine nexu pro quovis loco et tempore inter 1900 et 2100: Sol, Luna, planetae, 1627 stellae, constellationes, eventa et pagina de eclipsi 2027. Valores computati, non officiales.","tags":["astronomia","planetarium"]},"BRAZDA":{"line":"Discum Aureum Voyager gradatim decode, deinde novum discum pro sonda nunc lancienda encode. Imagines in primis gradibus schematicae sunt, non NASA.","detail":"Decoder et encoder 12 graduum pro Disco Aureo Voyager: celeritas, horologium hydrogenii, mappa pulsarum, signum imaginis, calibratio cum circulo, decodificatio lineatim, color, fasciculus tuus, contributiones et encodificatio disci 2026–2027.","tags":["Voyager","signum"]},"Arbore":{"line":"Arborem genealogicam tuam construe, cum personis, familiis, linea temporis et calculatore cognationis Romanice. Data in hoc navigatro tantum manent, sine synchronizatione.","detail":"Genealogia localis: personae, familiae, importatio/exportatio GEDCOM 5.5.1, diagrammata SVG, linea temporis, calculator cognationis (terminologia Romanica tantum). Sine synchronizatione; data in hoc navigatro manent.","tags":["genealogia","GEDCOM"]},"Gospodar":{"line":"Pecuniam domesticam observa: rationes, expensas, rationaria menstrua et relationes. Ratio non requiritur, sed si tesseram secretam amittis, data amittis. Non consilium pecuniarium.","detail":"Rationarium domesticum locale: rationes, categoriae, transactiones, importatio CSV, rationaria menstrua, relationes et calculatores cum formulis perspicuis. Sine ratione vel synchronizatione; tessera secreta amissa data amissa significat. Non consilium pecuniarium.","tags":["rationarium","res pecuniariae privatae"]},"Decibel":{"line":"Mensura quam sonorus sit strepitus circumstans et vide ex quibus sonis constet. Probationem auditus indicativam etiam habet. Non instrumentum certificatum; eventus a microphono pendent.","detail":"Sonometrum, analysator spectri (1/3 octavae, FFT) et probatio auditus indicativa. Non mensor certificatus et sine valore iuridico vel medico; lectiones a microphono et calibratione pendent.","tags":["sonus","mensuratio"]},"Provenienta":{"line":"Habesne imaginem et vis scire quis eam signaverit et quas editiones declaret? Subscriptionem digitalem adiunctam inspice. Experimentalis, in fasciculis exemplaribus tantum probata.","detail":"Inspector C2PA / Content Credentials localis, experimentalis: ostendit quis signaverit et quae editiones declaratae sint, et subscriptionem et ligamen ad bytes fasciculi verificat. In fasciculis syntheticis tantum probatus; sine indice fiduciae.","tags":["C2PA","origo"]},"Lexicon":{"line":"Dictionaria tua adfer et in eis verba quaere, etiam si sine diacriticis vel cum erroribus scribis. Solum parvum exemplum demonstrativum includit. Sine nexu.","detail":"Motor dictionarii sine nexu: dictionaria tua adfer (TSV/CSV, JSON, StarDict, dictd, XDXF) et quaere per praefixum, sine accentibus, approximate vel in toto textu. Series inclusa (345 ingressus) demonstrativa est, non dictionarium completum.","tags":["dictionarium","lingua"]},"VERIGA":{"line":"Nexus fractos in situ vel in plica invenit, itemque fasciculos sine proposito relictos. In Windows, macOS et Linux operatur; aliquam peritiam computatralem requirit.","detail":"Inspector nexuum (clean-room) pro situs interretialibus et plicis localibus, in Rust scriptus: linea mandatorum, applicatio nativa mensae (egui) et versio HTML fasciculi unici. Nexus HTML et CSS, redirectiones, ancoras #fragment, fasciculos orphanos, robots.txt et sitemap inspicit. Windows, macOS et Linux; licentia MIT.","tags":["inspectio nexuum","MIT"]},"TEZAUR":{"line":"Adiutor pro thesi tua qui ex libris et articulis tuis tantum scribit, cum citationibus verificabilibus. In computatro tuo operatur; documenta tua eum numquam relinquunt. Opus in progressu.","detail":"Adiutor investigationis localis ad thesim scribendam, in Rust scriptus, cum responsis in citationibus fundatis: libros et articulos tuos (PDF, EPUB, DOCX, txt) indicat, locos recuperat et ex eis tantum scribit, cum citationibus [n] inspectis et indice referentiarum. In computatro tuo cum exemplari locali operatur (Ollama, Jan, LM Studio); documenta tua eum numquam relinquunt. Versio 0.x; licentia MIT.","tags":["investigatio","MIT"]},"LegatorOCR":{"line":"Librum scande et PDF mundum cum paginis rectificatis et textu quaerendo accipe. In Windows, macOS et Linux operatur; scansiones tuae penes te manent.","detail":"Postprocessor clean-room in Rust scriptus pro libris scansis: paginas duplices dividit, obliquitatem rectificat, resecat, margines ponit, purgat et binarizat, deinde PDF vel imagines cum strato textus OCR quaerendi exportat. Applicatio graphica (Windows, macOS, Linux) et linea mandatorum, in 8 linguis. Recognitio textus (OCR) programma Tesseract separatum requirit; cetera sine eo operantur. Versio 0.x; licentia MIT.","tags":["scansio","MIT"]},"Fenarium":{"line":"Atlas et officina perceptionum subiectivarum per omnes sensus, a Phosphenismo incipiens: cursus 13 modulorum, experimenta ducta, simulator visualis et laboratorium auto-experimenti A/B fortuiti. Educativum, non instrumentum medicum.","detail":"Atlas phenorum (phosphenae, imagines posteriores, soni tinnito similes et plura), cursus 13 modulorum, laboratorium auto-experimentorum; non instrumentum medicum.","tags":["perceptio","MIT"]},"MENSURA":{"line":"IQ, EQ, CQ, RQ, functiones exsecutivas et sensus tuos cum 18 probationibus in 6 provinciis metire, cum indicibus compositis et intervallis fiduciae 95%. Normae provisoriae, indicativae tantum, non diagnosis.","detail":"18 probationes in 6 provinciis (IQ, EQ, CQ, RQ, functiones exsecutivae, sensus), indices cum intervallis fiduciae, exportatio/importatio JSON; normae provisoriae.","tags":["probationes","MIT"]},"Cronosala":{"line":"Horologia gymnasii: requies inter series, HIIT, Tabata, EMOM, AMRAP, circuitus et metronomus, itemque ephemeris exercitationis cum kg et repetitionibus.","detail":"Horologia gymnasii et ephemeris exercitationis in uno fasciculo HTML: requies adaptiva inter series, Interval/HIIT, Tabata, EMOM, AMRAP, circuitus stationum, tempo, metronomus, programma menstruum 4 hebdomadarum, catalogus exercitiorum et codices QR pro machinis. Data in navigatro manent; interfacies Romanica est.","tags":["sportus","tempus"]},"ScutSonor":{"line":"Sonus altus et stroboscopium lampadis pro congressibus cum canibus ferocibus, itemque manuale morum. Auxilium, non scutum certum.","detail":"Sweep 2–8 kHz, ultrasonum experimentale, sirenam et probationem altoparlantis generat, cum limitatore qui sonoritatem tenet, stroboscopio lampadis (2,5 Hz), modo lucis diurnae et manuali securitatis. Fasciculus unicus, sine vestigiis. Testimonia sonum canes arcere infirma sunt.","tags":["securitas","sonus"]},"MIRAJ":{"line":"Quomodo retina videat et quomodo cerebrum imaginem construat: fovea, macula caeca, illusiones et quiz, in tribus gradibus.","detail":"Explicatio interactiva visus in tribus gradibus (initiali, medio, provecto): retina, fovea, macula caeca, illusiones opticae, summarium et quiz 10 quaestionum. Fasciculus unicus, interfacies Romanica et Anglica.","tags":["visus","educatio"]},"ANTROPOS":{"line":"Profilum scientificum orientativum, localiter computatum: aetas biologica PhenoAge, vox, scriptio manu, delineatio horologii, personalitas TIPI et tempus reactionis.","detail":"Instrumentum perscrutationis educativum, non diagnosis: aetas biologica PhenoAge cum custode verisimilitudinis, analysis vocis, graphometria scripturae manuscriptae, probationes horologii et delineationis hominis, TIPI, probationes reactionis, relatio imprimibilis et exportatio JSON. Data in navigatro manent.","tags":["perscrutatio","biologia"]},"DESCANTAR":{"line":"Divinatio fabarum cum 41 fabis (methodus 3×3, variatio Oltenica) et 12 incantamentis traditionalibus, ut obiectum studii folkloricae.","detail":"Divinatio fabarum Romanica tribus methodis (3×3 ad regulam, Oltenia, tres acervi), lectiones per Caput, Cor et Pedes, 12 incantamenta traditionalia, phasis lunae, numerator recitationis, generator incantamentorum, historia et manuale exscribendum. Contentus folkloricus in 8 linguas cum AI translatus, a locutoribus nativis non recensitus.","tags":["folklorica","fabae"]},"Index-fara-frontiere":{"line":"Catalogus applicationum HTML fasciculi unici: collectio chiuta.github.io et res externae, cum quaestione et etiquettis.","detail":"Octo incepta ex collectione auctoris et octo res externae, clare notatae, cum quaestione viva, etiquettis premendis, commutatore RO/EN, themate obscuro/lucido et ingressu qui se ipsum catalogat. Nullae petitiones ad rete interretiale. Instantaneum staticum diei 5 Iulii 2026.","tags":["catalogus","res"]},"DECUPAJ":{"line":"Podcast, sonum vel video, in clipsa verticalia cum subtitulis converte, in ipso navigatro, sine ratione et sine aqua signo. Fasciculi tui instrumentum tuum numquam relinquunt.","detail":"Reels verticales ex podcast (sono vel video) in uno fasciculo HTML: segmentum in forma undae elige, suggestiones momentorum accipe, transcriptionem localem cum Whisper, subtitulos formatos, 4 proportiones imaginis (9:16, 4:5, 1:1, 16:9), seriem exportationis et MP4 per WebCodecs. Interfacies in 8 linguis.","tags":["series","video"]},"LECTOR":{"line":"Libri in ipso navigatro recitati: EPUB, DOCX, PDF, TXT vel textus insertus, sine ratione et sine servatro. Textus instrumentum tuum numquam relinquit.","detail":"Libros recitatos ex uno fasciculo HTML audi: EPUB, DOCX, PDF (cum OCR Romanico pro scansionibus), TXT; voces instrumenti vel Piper ro_RO, verbum dictum illuminatum, horologium somni, capitula, signa, dictionarium pronuntiationis, bibliotheca localis et themata dyslexiae amica. Interfacies in 8 linguis.","tags":["sonus","libri"]},"FARFURIA":{"line":"Dietetica digitalis gratuita: calories et macronutrientes personalizati, schema cibi 7 dierum, ephemeris cibi et observatio ponderis. Medicum vel dieteticum non substituit.","detail":"Dietetica digitalis in uno fasciculo HTML: metae caloriarum et macronutrientium (Mifflin–St Jeor, gradus actionis, finis), schema cibi 7 dierum cum filtris dietae et allergenorum, basis datorum cibi, ephemeris cibi et observatio ponderis. Regulae securitatis pro minoribus, historia perturbationum edendi et morbo renum. Interfacies in 8 linguis.","tags":["nutritio","salus"]},"VITALIS":{"line":"Comes privatus salutis, longaevitatis et biohackingis: novem columnae testimoniis ordinatae, calculatores, punctum vitae et ritus cotidianus. Non consilium medicum.","detail":"Comes salutis et longaevitatis in uno fasciculo HTML: novem columnae testimoniis ordinatae, calculatores (HOMA-IR, TyG, ratio ambitus ad altitudinem, Mifflin–St Jeor, zonae frequentiae cordis, cycli somni, protein), horologium ieiunii, gressus respirationis, punctum 360 cum diagrammate radar, intervalla referentiae biomarcatorum et observator ritus cotidiani. Comes non officialis eventus BioHacking360. Interfacies in 8 linguis.","tags":["salus","longaevitas"]},"REZONANTA":{"line":"Manuale et instrumenta ad communicationem et media: nuntius, canales, communicatum pressae, colloquium, claritas, consilium et discrimen.","detail":"Quomodo efficias ut te audiant, in uno fasciculo HTML: 12 principia cum probatione practica, “domus nuntii” (oratio 30 secundorum, relatio, versio brevis et dicta), commendationes canalium medialium, generator communicatorum pressae in pyramide inversa, tabula colloquii, analysator claritatis textus, consilium communicationis cum exportatione textus/CSV et gradus primae horae discriminis. Interfacies in 8 linguis.","tags":["communicatio","media"]},"Claritas":{"line":"Extensio navigatri omnia-in-una ad accessibilitatem: correctio contrastus, modus lectoris, lectio recitata et recensio WCAG. Sine telemetria, sine rete, sine ratione.","detail":"Extensio accessibilitatis gratuita pro navigatro: correctio contrastus automatica (WCAG AA/AAA), themata contrastus alti, filtra caecitatis colorum, textus maior et fontes dyslexiae amici, regula lectionis, larva et lupa, modus lectoris, lectio recitata, scopae clicki magnae et scansio unius commutatoris, recensio WCAG 2.2, imagines ecrani locales et registratio ecrani. Pro Chromium, Firefox et Safari; interfacies in 8 linguis.","tags":["accessibilitas","extensio"]},"TurboCursa":{"line":"Cursus arcade pseudo-3D in Rust scriptus: paesagia ex semine generata, 11 modi, curriculum divisionum et 2 lusores. Originalis, sine codice vel bonis ex alio ludo.","detail":"Cursus arcade pseudo-3D clean-room in Rust scriptus: motor, ars, musica et nomen originalia, omnia ex semine generata (19 paesagia), expeditio, cursus contra tempus, infinitus, Rush Hour, slalom, speculum, Blackout, Zen, contra CPU, ecranum divisum duorum lusorum et curriculum divisionum. Natively vel ut fasciculus interretialis operatur; interfacies in 8 linguis.","tags":["cursus","Rust"]},"ANTENA":{"line":"Opus in progressu: solutor antennarum filarium cum NEC-2 compatibilis (methodus momentorum) cum fronte in navigatro. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: solutor antennarum filarium cum NEC-2 compatibilis (methodus momentorum) cum fronte in navigatro. Adhuc tantum sceleton pre-alpha.","tags":["radiotelegraphia","antennae"]},"ARBITRU":{"line":"Opus in progressu: motor regularum universalis pro ludis tabularum, chartarum, tesserarum et aenigmatum, cum lingua regularum declarativa. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: motor regularum universalis pro ludis tabularum, chartarum, tesserarum et aenigmatum, cum lingua regularum declarativa. Adhuc tantum sceleton pre-alpha.","tags":["ludi","regulae"]},"ASTROLABIU":{"line":"Opus in progressu: motor eventorum caeli (scalae temporis, eclipses, ortus et occasus, calendaria), in Rust puro. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: motor eventorum caeli (scalae temporis, eclipses, ortus et occasus, calendaria), in Rust puro. Adhuc tantum sceleton pre-alpha.","tags":["astronomia","calendaria"]},"ECOGRAMA":{"line":"Opus in progressu: editor spectrogrammatis et restauratio soni: in spectrogrammate elige, refice, exporta. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: editor spectrogrammatis et restauratio soni: in spectrogrammate elige, refice, exporta. Adhuc tantum sceleton pre-alpha.","tags":["sonus","restauratio"]},"ecou-spectral-rs":{"line":"Opus in progressu: editor spectrogrammatis nativus in Rust cum plugins ad reductionem strepitus et detectionem vocis. Sceleton codicis et formam plugin habet, sed nondum functionem perfectam.","detail":"Opus in progressu: editor spectrogrammatis nativus in Rust cum plugins ad reductionem strepitus et detectionem vocis. Sceleton codicis et formam plugin habet, sed nondum functionem perfectam.","tags":["sonus","Rust"]},"MARTOR":{"line":"Opus in progressu: captura interretialis forensica in WARC/WACZ cum hashes, subscriptionibus et notis temporis fide dignis, sine nexu verificabilis. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: captura interretialis forensica in WARC/WACZ cum hashes, subscriptionibus et notis temporis fide dignis, sine nexu verificabilis. Adhuc tantum sceleton pre-alpha.","tags":["archivatio","testimonia"]},"NEAMURI":{"line":"Opus in progressu: motor cognationis, a via arboris genealogicae ad rectum terminum cognati in multis linguis. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: motor cognationis, a via arboris genealogicae ad rectum terminum cognati in multis linguis. Adhuc tantum sceleton pre-alpha.","tags":["cognatio","genealogia"]},"TACTIL":{"line":"Opus in progressu: stratum exitus tactilis: formae braille (BRF, Unicode), ostensores, impressores in relief et vibratio ecrani tactilis. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: stratum exitus tactilis: formae braille (BRF, Unicode), ostensores, impressores in relief et vibratio ecrani tactilis. Adhuc tantum sceleton pre-alpha.","tags":["braille","accessibilitas"]},"atelier-verificare":{"line":"Photographias, video, nexus et dominia in navigatro tuo inspice, nihil impositum: genus fasciculi verum et SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (lectio tantum), analysis gradus erroris. Probare non potest photographiam authenticam esse. Alpha.","detail":"Instrumentarium verificationis pro diurnariis et lectoribus diligentibus, localiter operans. Imagines, video, nexus, dominia vel textum adde et inventa cum gradu sollicitudinis pro singulis accipe: genus fasciculi verum, SHA-256, EXIF et positio GPS, XMP et IPTC, vestigia generatorum imaginum AI, manifesta Content Credentials (C2PA; lecta, non validata), analysis gradus erroris pro JPEG, metadata video cum fotogrammatibus clavibus ad quaestionem imaginum inversam, et anatomia nexus. Duae inspectiones retis optionales (summarium DNS, Internet Archive) tantum post cistulam consensus notatam currunt. Relatio (Markdown, JSON vel PDF) fines methodi enumerat. Probare non potest photographiam authenticam esse: metadata absentia parum dicit et metadata falsificari possunt. Alpha; novem ex undecim inspectionibus sine nexu operantur; fasciculi in navigatro manent.","tags":["diurnarii","verificatio","photographiae"]},"balanta":{"line":"Exemplaria AI caeco compara: responsa duorum ad octo exemplarium ad 92 mandata Romanica, Anglica et Hungarica insere, A vel B suffragium da, et ordinem cum intervallis accipe. Alpha; sine nexu operatur.","detail":"Aestimatio caeca iuxta se posita exemplarium AI Romanice. Responsa cuiusque exemplaris ipse inseris (nihil vocatur: sine clavibus API, sine rationibus), applicatio nomina exemplarium in responsis celat, ordinem ex semine figit et suffragium tuum notat. Ordo Bradley–Terry et Elo cum intervallis bootstrap 95% utitur, itemque proportione victoriarum, errore positionis et tabulis contra singulos. Suffragia et responsa fasciculi JSON Lines aperti sunt. Cum paucis suffragiis vel mandatis ordo nihil generale dicit. Alpha; data in navigatro manent; sine vestigiis.","tags":["AI","aestimatio"]},"calendarium":{"line":"Diem in quovis ex undecim calendariis (Gregoriano, Iuliano, Hebraeo, Hijri, Persico, Sinico, Maya, Martis…) scribe et eum in omnibus aliis vide, cum aspectu mensis. Alpha; sine nexu operatur.","detail":"Dies inter undecim calendaria convertit (Gregorianum, Iulianum, Iulianum Emendatum, Hebraeum, Hijri, Persicum, Copticum, Aethiopicum, Sinicum, Maya et Dies Solaris Martis), diem Iulianum, diem hebdomadis et hebdomadam ISO ostendit, et aspectum mensis cum secundo calendario sub quoque die habet. Notas Romanicas (stilus vetus et novus, mutatio 1919, Pascha) et atlantem calendariorum includit, unum plugin per calendarium. Valores computantur, cum finibus declaratis (calendarium Hijri tabulare est; spatia custodiuntur). Alpha, in 8 linguis, sine nexu operatur; sine vestigiis.","tags":["calendaria","tempus"]},"glosar":{"line":"Dictionarium sine nexu pro Aromanice, Megleno-Romanice et Romani: sine diacriticis quaere, vide quae verba fundamentalia desint, verba cum fonte et registratione adde. Alpha.","detail":"Dictionaria pro linguis minoritatum et periclitantibus, ab eorum locutoribus condita. Quaestiones diacriticos neglegunt, fidem ostendunt (rudimentum, cum fonte, recensitum), tabulam ambitus 50 notionum fundamentalium habent, et verba cum fonte, licentia et registratione (usque ad 50 KB) addere sinunt. Fasciculos TSV et Anki et fasciculum contributionis pro incepto exportat. Indices initiales parvi sunt — numeri et pauca verba, quaeque cum fonte publicato — et nullus locutor eos adhuc recensuit. Alpha; sine nexu operatur; data in navigatro manent donec deferas.","tags":["linguae","dictionaria"]},"graiul":{"line":"Archivum folkloris Romanici sine nexu (proverbia, incantamenta, aenigmata, carmina natalicia) cum fonte, comitatu et consensu. Cum decem proverbiis incipit; plura addere potes. Alpha.","detail":"Quaestio diacriticos neglegens, cum filtris per genus, comitatum et fidem; proverbium diei (idem pro omnibus in data die), mappa schematica tegularum 41 comitatuum et Bucarestii, et forma additionis quae fontem requirit et, pro incantamentis et quibuscumque a persona collectis, consensum. Fasciculum contributionis et TSV exportat. Data initialia decem proverbia Romanica ex Wikiquote sunt; nullum a folkloristico recensitum est. Alpha; sine nexu operatur; data in navigatro manent donec deferas.","tags":["folklorica","archivum"]},"indicativ-international":{"line":"Quaestiones examinis radiotelegraphiae amatoriae exerce cum schemate repetitionis quinque cistularum et examinibus simulatis temporatis; fasciculos quaestionum in una forma JSON communi importa. 50 quaestiones exercitii inclusae; non bancus officialis. Alpha.","detail":"Exercitator et simulator examinis pro quaestionibus licentiae radiotelegraphiae amatoriae, cum forma fasciculorum communi ut omnis terra suum bancum addere possit. “Exercitium” responsa recta post 1, 3, 7, 14 et 30 dies repetit et quodque responsum cum suo fonte explicat; “Examen” probatio temporata cum limine transeundi est; “Fasciculi” fasciculos importat et inspicit et progressum tuum subsidio munit. Fasciculus inclusus 50 quaestiones exercitii originales ad hoc inceptum scriptas continet — non bancus officialis — et nullus fasciculus nationalis adhuc includitur. Alpha; sine nexu operatur; progressus in navigatro manet.","tags":["radiotelegraphia","examina"]},"proiector-fara-frontiere":{"line":"Telephona scholae in ecranum commune vertuntur, sine servatro et sine ratione: horologium, suffragatio, quiz, notae et tabula alba, per codicem QR vel textum insertum in eadem rete copulata. Alpha: in telephonis veris nondum probatum.","detail":"Ecranum commune pro schola, sine servatro et sine ratione. Magister paginam ad proiectorem aperit; telephonum cuiusque discipuli codice commutato iungitur (tabulae QR, photographia codicis vel textus insertus), usque ad 30 telephona simul. Quinque activitates includuntur: horologium retrogradum, suffragatio cum barris vivis, quiz (quaestiones ex fasciculo JSON, textus simplicis vel CSV; responsum rectum in proiectore manet donec revelatur; bonus celeritatis et tabula punctorum), notae adhaesivae et tabula alba cum uno colore per telephonum. Eventus servari possunt ut CSV, textus vel PNG. Quaeque activitas in tabula isolata cum solis permissionibus quas declarat currit, et nova activitas unum descriptorem et unum scriptum est. Magister telephonum claudere vel removere et sessionem finire potest; omne instrumentum linguam suam (octo) et speciem (obscuram, contrastum altum, textum magnum) eligit. Sine nexu operatur semel aperta et installari potest. Alpha: in Chromium cum nexibus veris in una machina probata, non in telephonis veris, aliis navigatris vel retibus scholasticis. Copulatio eandem rete localem requirit (sine relais), adresam IP cuiusque instrumenti alteri ostendit et quis alterum instrumentum sit non verificat. Forma quiz “Undava” non sustinetur: nulla specificatio inventa est.","tags":["schola","proiectio","quiz"]},"regula":{"line":"Quinque ludos classicos duorum lusorum (Nine Men’s Morris, Alquerque, Fanorona, Mū tōrere, Hnefatafl) contra computatrum vel amicum lude; ludum tuum ut JSON adde. Alpha; sine nexu operatur.","detail":"Unus motor regularum pro ludis tabularibus traditionalibus: quisque ludus fasciculus JSON est, et textus regularum in octo linguis ex iisdem datis generatur quibus motor ludit, ergo textus et ludus dissentire non possunt. Quaeque pars persona, lusor fortuitus vel computatrum duobus gradibus esse potest; revocatio, restitutio, indicium et acta motuum exscribenda. Ludum tuum inserere, validare et ludere potes. Ludi reconstructiones sunt, non regulae torneamentorum, et quisque declarat quam certae sint regulae eius. Alpha; sine nexu operatur; sine vestigiis.","tags":["ludi","regulae"]},"vietar-packs":{"line":"Fasciculos specierum regionalium pro VietAR perlustra, importa, inspice et crea: nomina in pluribus linguis, signa toxicitatis, similia periculosa. Quinque fasciculi initiales rudimentarii cum 71 speciebus. Alpha; sine nexu operatur.","detail":"Fasciculi specierum regionalium pro VietAR: nomina in pluribus linguis, signum toxicitatis, similia periculosa, et locus pro photographiis licentiatis et nexibus sonorum. Quinque fasciculos initiales perlustra et quaere (Romania: plantae et fungi, aves, mammalia; Bulgaria et Moldavia: sceleta), fasciculum importa, eum iisdem regulis ac repositorium inspice, vel unum pro classe scholastica vel circulo naturae crea. Fasciculi initiales rudimenta sunt sine photographiis vel sonis, et “non notatum toxicum” numquam significat edule vel tutum. Applicatio VietAR fasciculos nondum importare potest. Alpha; sine nexu operatur.","tags":["natura","species"]},"PatruZeci":{"line":"Atlas illustratus et animatus usuum WD-40: manuale 147 chartarum et index officialis 1993 usuum, quisque cum scaena animata propria. Non officialis, sine nexu, sine ratione.","detail":"Atlas illustratus et animatus usuum aerosolis WD-40 in uno fasciculo sine nexu: manuale 147 chartarum in 14 categoriis (cum gradu periculi et quid aerosol faciat), index officialis “2000+ usuum” cum 1993 ingressibus, et sectio 25 usuum additorum, mythorum et monitorum ex articulis interretialibus. 131 variantes scaenarum animatarum, filtra per categoriam et functionem, interfacies in 8 linguis. Applicatio non officialis, independens.","tags":["WD-40","manu facta"]},"ODISEEA":{"line":"Documentarium circiter 4,5 minutorum de Voyager 1 et 2, in uno fasciculo HTML: scaenae in charta graphica generatae, exportatio 2D et 3D pro perspicillis VR, in 8 linguis.","detail":"Documentarium circiter 4,5 minutorum de sondis Voyager 1 et 2, in uno fasciculo HTML qui localiter in navigatro currit, sine servatro et sine installatione. Scaenae procedurales in charta graphica generatae (WebGL): planetae, sonda, rocheta, antenna DSN, Discus Aureus, heliosphaera, Pale Blue Dot. Imagines publicae NASA/JPL et Wikimedia Commons, vel imago tua pro quaque scaena. Exportatio 2D, 3D dimidia (1920×1080) et plena (3840×1080) iuxta se posita, et modus telephoni pro perspicillis VR ut VR BOX; musica ambientalis in navigatro generata, narratio optionalis. Interfacies, narratio, subtituli et nomina in 8 linguis.","tags":["Voyager","documentarium"]},"EXIF-CURAT":{"line":"Opus in progressu: instrumentum ad data occulta in fasciculis (imagines, PDF, Office, video: EXIF, GPS, XMP) videnda et removenda, cum analysatoribus memoriae tutis, in Rust scriptum. Adhuc tantum sceleton pre-alpha.","detail":"Opus in progressu: instrumentum ad data occulta in fasciculis (imagines, PDF, Office, video: EXIF, GPS, XMP) videnda et removenda, cum analysatoribus memoriae tutis, in Rust scriptum. Adhuc tantum sceleton pre-alpha.","tags":["metadata","secretum"]},"PORUMBEL":{"line":"Photographias quas cum Open Camera in telephono tuo capis sponte in plicam in computatro tuo transfert, una plica per sessionem, et in LegatorOCR aperit. Sine ratione, sine nube, sine crates tertiorum.","detail":"Programma parvum in Rust scriptum, sine crates tertiorum (Windows, macOS, Linux), quod photographias cum Open Camera captas in computatrum tuum affert: per Wi-Fi (pagina impositionis vel WebDAV, cum codice QR), per ADB (USB vel Wi-Fi) vel ex plica synchronizata (Syncthing etc.). Photographias in unam plicam per sessionem captionis ordinat et quamque sessionem perfectam in LegatorOCR aperit (divisio, rectificatio, resectio, PDF cum OCR). Tabula moderationis localis et mandatum “porumbel doctor” ad diagnosin; nihil rete tuam relinquit. Versio 0.x; licentia MIT.","tags":["photographiae","translatio fasciculorum"]},"colibri-companion":{"line":"Applicatio mensae amica pro colibri, motore inferentiae locali: exemplar quod computatro tuo convenit elige, uno click defer et cum eo collocutor. Sine ratione, sine officio nubis.","detail":"Applicatio mensae in Rust scripta pro colibri (JustVugg/colibri): Python et colibri invenit, tantum exemplaria quae memoriae computatri tui conveniunt ostendit, ea cum pausa et resumptione defert, servatrum locale incipit et colloquium aperit (responsa fluentia, Markdown, colloquia servata, quaestio, documenta localia et instrumenta MCP cum approbatione in omni vocatione). Tabula Resourcum processorem, memoriam, chartam graphicam et nexus apertos ostendit. Windows, macOS, Linux; interfacies in 8 linguis; licentia Apache-2.0.","tags":["AI localis","mensa"]},"CartaColibri":{"line":"Bibliotheca AI localis in motore Colibrì: plicas quas eligis indicat, eas celeriter quaerit et exemplar locale rogat ut summarium faciat, data extrahat vel synthesin faciat, semper fasciculum fontis citans. Nihil computatrum tuum relinquit.","detail":"Programma in Rust scriptum, cum pagina locali (127.0.0.1) et linea mandatorum. Plicas quas eligis indicat (originalia tantum leguntur, numquam mutantur), textum plenum quaerit (verba, “locutiones”, praefixum*, AND/OR/NOT, filtra per genus, magnitudinem, locum) et fasciculos in greges ordinat. Exemplar Colibrì locale summarium facit, extrahit (tabula vel JSON, “NON INVENTUM” loco coniecturarum), synthesin facit vel comparat, semper cum fontibus citatis [S1], [S2] et puncto fundationis. Navigatrum parvum web-grab, servatrum MCP lectionis tantum, importationes (signa, Obsidian, Zotero, RSS) et inspectionem textus tui contra bibliothecam etiam habet. Sine ratione, sine telemetria; interfacies in 8 linguis; versio alpha 0.2; licentia MIT.","tags":["AI localis","bibliotheca"]},"PolyTabletop":{"line":"240 ludi tabulares quos contra computatrum ludere potes, in terminali vel in fenestra graphica, itemque ludus duorum lusorum ad unam tabulam clavium vel per rete. In Rust scriptum; motor et ludi dependentias externas non habent.","detail":"Collectio ludorum tabularium clean-room in Rust scripta: 240 ludi ludibiles contra computatrum, in terminali vel in fenestra graphica, itemque ludus vicissim et per rete duorum lusorum. Classica abstracta, ludi chartarum et tesserarum, variantes originales mechanicarum modernarum sub nominibus propriis, ludi cooperativi cum socio AI, ludi rolarum occultarum, ludi convivales et verbales; catalogus 1200 ingressus habet, cum instrumentario ludorum rolarum (tesserae, tabulae, generator carcerum, simulator pugnae). Adversarius AI (alpha-beta, MCTS), arena AI contra AI, transcripta et repetitiones. Interfacies in 8 linguis; versio 0.9; licentia MIT vel Apache-2.0.","tags":["ludi tabulares","Rust"]},"STRAJA":{"line":"Scutum contra agentes AI qui telephonum tuum legunt: ostendit quae applicationes notificationes, ecranum, photographias et SMS tua legere possint, te monet cum nova aditum accipit et te ad paginam optionum ducit ubi eum revocas. Sine ratione, sine permissione INTERNET.","detail":"Applicatio pro Android (APK) et iPhone (IPA non subscriptum). In Android applicationes cum aditu ad notificationes, officiis accessibilitatis, rola adiutoris et permissionibus mediorum et SMS enumerat, cum puncto periculi per applicationem et pro toto telephono; monitor periodicus telephonum cum basi comparat et de omni novo aditu te monet. Paginam optionum systematis exactam aperit ad aditum revocandum et nihil tacite mutat. Aditus temporarius cum admonitione, et manuale protectionis 12 punctorum. In iPhone nulla recensio est (iOS permissiones aliarum applicationum celat), tantum manuale, registrum manuale et admonitiones. Agentem sistere non potest. Sine permissione INTERNET, sine subsidio; 8 linguae; versio 1.0; licentia MIT.","tags":["secretum","telephonum"]},"CUPLAJ":{"line":"Telephonia lineae communis pro theatro immersivo: classis telephonorum Android ordinariorum in centralem telephonicam privatam per Wi-Fi loci vertitur, sine nube, sine rationibus, sine publicitate. Proprium eius est “cuplaj”: linea communis telephonorum fixorum ab annis 1980 ad circiter 2006.","detail":"Applicatio Android (APK) et applicatio iPhone/iPad (IPA non subscriptum). Ordinatores et actores cum spectatoribus per Wi-Fi locale colloquuntur; unum telephonum (moderator) centralis est. Sex aetates telephonicae (1985 rotarium, 1995 clavium, 2003 mobile, 2025 smartphone, 2045 gestabilia, 2080 mens communis), linea communis ubi duo subscriptores unam lineam communicant, vocationes veras, publica allocutio premendo-ad-loquendum, canalis post scaenam, signa (textus plenus ecrani, vibratio, sonitus, flash, vox dicta, vocatio phantasma) et scriptum cum GO et PLAY. Sine infrastructura, clavis retis AES-128-GCM optionalis, vocationes P2P directae. Sine analytica, sine servatris, sine rationibus. 8 linguae; versio 1.10; licentia MIT.","tags":["theatrum immersivum","telephonia"]},"LUSTRUM":{"line":"Telephonum tuum recupera: quisquilias, duplicata, photographias similes et reliquias applicationum invenit, easque tantum cum approbatione tua purgat. Permissionem INTERNET non habet, ergo physice nihil usquam mittere potest.","detail":"Applicatio Android (Kotlin). Repositio per genus fasciculi, fasciculi magni, vetusti et quisquiliae, duplicata exacta (magnitudo, vestigium celere, deinde SHA-256), photographiae similes (hashing perceptuale), reliquiae applicationum deinstallatarum, compressio JPEG, caches, photographiae obscurae et obscuratae, Swiper (sinistrorsum = dele, dextrorsum = serva), purgatio programmata et cista 30 dierum LUSTRUM ad revocandum. Sine permissione INTERNET: nihil telephonum relinquit. Nulla magia radicis: Android 11+ omnem applicationem ordinariam a plicis datorum aliarum applicationum prohibet. 8 linguae (translationes machinales); versio beta 0.8; licentia MIT.","tags":["purgator telephoni","Android"]},"STENOGRAMA":{"line":"Transcriptio soni longi in ipso navigatro, cum Whisper locali: fasciculus HTML unicus, sine ratione, sine servatro, sine aqua signo. Fasciculus soni tuus instrumentum numquam relinquit; tantum exemplar Whisper semel defertur.","detail":"MP3 et WAV per partes legit (ergo longitudo a memoria non limitatur); alia formata (M4A, OGG/Opus, MP4, FLAC) tota decodificantur. Quaeque pars in pausa secatur ne verba dividantur; progressus servatur, ergo sistere et resumere potes. Editor in pagina (tempus preme ut locum audias), remotio phrasium phantasmaticarum Whisper typicarum, exportatio in .txt, .srt, .vtt, .docx vel ad clipboard. WebGPU utitur cum praesto est, alioqui processore (WASM). PWA installabilis; exemplar post primam delationem in cache manet. Bibliotheca ex jsDelivr in prima transcriptione oneratur, per SHA-384 inspecta. Interfacies in 7 linguis; licentia MIT.","tags":["transcriptio","sonus"]},"GERMEN":{"line":"Exemplar linguae parvum a fundamentis in Rust puro, in CPU ordinario trahe: sine Python, sine CUDA, sine ratione, sine accessu retis, sine telemetria. Unum binarium, unus fasciculus textus, unum mandatum.","detail":"Programma Rust (in Burn, cum eius backend CPU in Rust puro) quod rete stili GPT trahit super bytes vel super vocabularium BPE ex textu tuo discitum, deinde ex exemplari tracto textum generat. GERMEN Studio: fenestra localis (127.0.0.1) cum curva damni, celeritate et exemplis textus, in 8 linguis. Mandata ad celeritatem computatri tui mensurandam et ad fasciculos exemplaris inspiciendos et reficiendos. Officina est ad discendum et experiendum, non fabrica colloquentium: exemplar 1–25 miliones parametrorum formam textus discit, non scientiam mundi. Sine GPU, sine praecisione mixta. Versio 0.6; licentia MIT.","tags":["AI localis","Rust"]},"CUANTOR":{"line":"Simulator computatri quantici pro mensa tua, a 5 ad 1000 qubits, cum interfacie in stilo IBM Quantum Composer. Mathematica exacta, sed non hardware quanticum verum.","detail":"Programma Rust in quattuor partibus (nucleus, fenestra, linea mandatorum, nexus IBM) pro Windows, macOS et Linux. Tabula delineandi qualis IBM Composer: portas coloratas in lineis (qubits) pone et vide barras et sphaeram eventum ostendere, dum panel textus idem circuitum vivum in OpenQASM et Qiskit scribit. Tres calculatores: unus qui omnem numerum meminit (usque ad 28 qubits), unus celerrimus pro portis simplicibus (usque ad 4096) et unus pro circuitibus cum paucis ramis. Mensura, reset et if in medio cursu, portae tuae, strepitus simulatus, eventus repetibiles cum semine. OpenQASM 2.0 et 3.0 legit; circuitum in IBM Composer aperire vel ad machinam IBM veram cum clave rationis tuae mittere potes (in hardware IBM vero non verificatum). Interfacies in 8 linguis; versio 0.2.","tags":["computator quanticus","simulator"]},"ERATA":{"line":"Corrector in navigatro qui orthographiam, grammaticam, interpunctionem et typographiam in ipso computatro tuo inspicit: sine ratione, sine servatro, sine telemetria. Profundissimus pro lingua Romanica.","detail":"Extensio pro Chromium et Firefox (versio Safari non probata), a fundamentis scripta sine ullo codice, regulis vel datis ex LanguageTool vel alio inspectore. In campis textarea, input et contenteditable operatur et subliniationes suas sine pagina mutanda delineat. Linguam per paragraphum detegit, diacritica (ro, fr, es, pt) restituit tantum ubi correctio non ambigua est, et regulas Romanicas profundas habet (virgula inferior ș/ț, “să/sa”, “într-un”, virgula ante “dar/însă”). Dictionarium personale, regulae propriae, commutator per situm, importatio dictionariorum Hunspell. Reformulatio optionalis per exemplar locale (localhost tantum, ex defectu exstincta). Interfacies in 25 linguis. Versio 0.4; licentia MIT.","tags":["correctio","extensio"]}});
